package com.inventoryclickhighlight;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(InventoryClickHighlightConfig.CONFIG_GROUP)
public interface InventoryClickHighlightConfig extends Config
{
	String CONFIG_GROUP = "inventoryclickhighlight";

	@Alpha
	@ConfigItem(
		keyName = "outlineColor",
		name = "Outline color",
		description = "Color of the glow outline on clicked inventory items.",
		position = 0
	)
	default Color outlineColor()
	{
		return new Color(255, 200, 0, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "overlayColor",
		name = "Overlay color",
		description = "Color of the fill overlay on clicked inventory items.",
		position = 1
	)
	default Color overlayColor()
	{
		return new Color(255, 200, 0, 100);
	}

	@Range(
		min = 100,
		max = 10000
	)
	@ConfigItem(
		keyName = "fadeDurationMs",
		name = "Fade duration (ms)",
		description = "How long the highlight takes to fade out after clicking an item.",
		position = 2
	)
	default int fadeDurationMs()
	{
		return 200;
	}

	@ConfigItem(
		keyName = "excludedActions",
		name = "Excluded actions",
		description = "Comma-separated list of left click actions which shouldn't be highlighted (e.g. \"Use, Eat, Drop\")",
		position = 3
	)
	default String excludedActions()
	{
		return "";
	}
}

package com.inventoryclickhighlight;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;

class InventoryClickHighlightOverlay extends WidgetItemOverlay
{
	private static final int INVENTORY_SIZE = 28;

	private final ItemManager itemManager;
	private final InventoryClickHighlightPlugin plugin;
	private final InventoryClickHighlightConfig config;

	@Inject
	private InventoryClickHighlightOverlay(
		ItemManager itemManager,
		InventoryClickHighlightPlugin plugin,
		InventoryClickHighlightConfig config)
	{
		this.itemManager = itemManager;
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (itemId <= 0)
		{
			return;
		}

		Widget widget = widgetItem.getWidget();
		if (!isMainInventoryItemWidget(widget))
		{
			return;
		}

		int slot = widget.getIndex();
		if (slot < 0 || slot >= INVENTORY_SIZE)
		{
			return;
		}

		float fade = plugin.getFadeProgress(slot);
		if (fade <= 0)
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();

		Color outlineColor = config.outlineColor();
		int outlineAlpha = (int) (outlineColor.getAlpha() * fade);
		if (outlineAlpha > 0)
		{
			Color fadedOutline = ColorUtil.colorWithAlpha(outlineColor, outlineAlpha);
			BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), fadedOutline);
			graphics.drawImage(outline, bounds.x, bounds.y, null);
		}

		Color overlayColor = config.overlayColor();
		int overlayAlpha = (int) (overlayColor.getAlpha() * fade);
		if (overlayAlpha > 0)
		{
			Color fadedOverlay = ColorUtil.colorWithAlpha(overlayColor, overlayAlpha);
			Image fill = ImageUtil.fillImage(
				itemManager.getImage(itemId, widgetItem.getQuantity(), false),
				fadedOverlay);
			graphics.drawImage(fill, bounds.x, bounds.y, null);
		}
	}

	private static boolean isMainInventoryItemWidget(Widget widget)
	{
		while (widget != null)
		{
			if (widget.getId() == InterfaceID.Inventory.ITEMS)
			{
				return true;
			}
			widget = widget.getParent();
		}
		return false;
	}
}

package com.inventoryclickhighlight;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Inventory Click Highlight"
)
public class InventoryClickHighlightPlugin extends Plugin
{
	static final int INVENTORY_SIZE = 28;

	@Inject
	private Client client;

	@Inject
	private InventoryClickHighlightConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private InventoryClickHighlightOverlay overlay;

	private final long[] slotHighlightStartMs = new long[INVENTORY_SIZE];

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clearHighlights();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		int slot = getClickedInventorySlot(event);
		if (slot < 0)
		{
			return;
		}

		if (isActionExcluded(event.getMenuOption()))
		{
			return;
		}

		slotHighlightStartMs[slot] = System.currentTimeMillis();
	}

	float getFadeProgress(int slot)
	{
		long start = slotHighlightStartMs[slot];
		if (start == 0)
		{
			return 0;
		}

		int durationMs = config.fadeDurationMs();
		if (durationMs <= 0)
		{
			slotHighlightStartMs[slot] = 0;
			return 0;
		}

		long elapsed = System.currentTimeMillis() - start;
		if (elapsed >= durationMs)
		{
			slotHighlightStartMs[slot] = 0;
			return 0;
		}

		return 1f - ((float) elapsed / durationMs);
	}

	private int getClickedInventorySlot(MenuOptionClicked event)
	{
		if (!isInventoryItemClick(event.getMenuAction()))
		{
			return -1;
		}

		if (event.getParam1() == InterfaceID.Inventory.ITEMS && event.getParam0() >= 0)
		{
			return event.getParam0();
		}

		Widget widget = event.getWidget();
		if (widget == null)
		{
			return -1;
		}

		if (WidgetUtil.componentToInterface(widget.getId()) != InterfaceID.INVENTORY)
		{
			return -1;
		}

		if (!isMainInventoryItemWidget(widget))
		{
			return -1;
		}

		return widget.getIndex();
	}

	private static boolean isMainInventoryItemWidget(Widget widget)
	{
		while (widget != null)
		{
			if (widget.getId() == InterfaceID.Inventory.ITEMS)
			{
				return true;
			}
			widget = widget.getParent();
		}
		return false;
	}

	private static boolean isInventoryItemClick(MenuAction action)
	{
		switch (action)
		{
			case CC_OP:
			case CC_OP_LOW_PRIORITY:
			case WIDGET_TARGET:
			case WIDGET_USE_ON_ITEM:
			case WIDGET_TARGET_ON_WIDGET:
				return true;
			default:
				return false;
		}
	}

	private void clearHighlights()
	{
		for (int i = 0; i < INVENTORY_SIZE; i++)
		{
			slotHighlightStartMs[i] = 0;
		}
	}

	private boolean isActionExcluded(String menuOption)
	{
		String excluded = config.excludedActions();
		if (excluded == null || excluded.isEmpty())
		{
			return false;
		}

		if (menuOption == null)
		{
			menuOption = "";
		}

		for (String part : excluded.split(","))
		{
			String action = part.trim();
			if (!action.isEmpty() && action.equalsIgnoreCase(menuOption.trim()))
			{
				return true;
			}
		}

		return false;
	}

	@Provides
	InventoryClickHighlightConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(InventoryClickHighlightConfig.class);
	}
}

package com.inventoryclickhighlight;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class InventoryClickHighlightPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(InventoryClickHighlightPlugin.class);
		RuneLite.main(args);
	}
}
